// MinimockFreezeInspect logs each unmet expectation
func (m *UsersSvcMock) MinimockFreezeInspect() {
	for _, e := range m.FreezeMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to UsersSvcMock.Freeze at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterFreezeCounter := mm_atomic.LoadUint64(&m.afterFreezeCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.FreezeMock.defaultExpectation != nil && afterFreezeCounter < 1 {
		if m.FreezeMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to UsersSvcMock.Freeze at\n%s", m.FreezeMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to UsersSvcMock.Freeze at\n%s with params: %#v", m.FreezeMock.defaultExpectation.expectationOrigins.origin, *m.FreezeMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcFreeze != nil && afterFreezeCounter < 1 {
		m.t.Errorf("Expected call to UsersSvcMock.Freeze at\n%s", m.funcFreezeOrigin)
	}

	if !m.FreezeMock.invocationsDone() && afterFreezeCounter > 0 {
		m.t.Errorf("Expected %d calls to UsersSvcMock.Freeze at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.FreezeMock.expectedInvocations), m.FreezeMock.expectedInvocationsOrigin, afterFreezeCounter)
	}
}

