// Times sets number of times UsersSvc.Update should be invoked
func (mmUpdate *mUsersSvcMockUpdate) Times(n uint64) *mUsersSvcMockUpdate {
	if n == 0 {
		mmUpdate.mock.t.Fatalf("Times of UsersSvcMock.Update mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmUpdate.expectedInvocations, n)
	mmUpdate.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmUpdate
}

func (mmUpdate *mUsersSvcMockUpdate) invocationsDone() bool {
	if len(mmUpdate.expectations) == 0 && mmUpdate.defaultExpectation == nil && mmUpdate.mock.funcUpdate == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmUpdate.mock.afterUpdateCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmUpdate.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// Update implements mm_grpcapi.UsersSvc
func (mmUpdate *UsersSvcMock) Update(ctx context.Context, actorID string, scopeAll bool, id string, roleSlugs []string, email string, username string) (u1 domain.User, err error) {
	mm_atomic.AddUint64(&mmUpdate.beforeUpdateCounter, 1)
	defer mm_atomic.AddUint64(&mmUpdate.afterUpdateCounter, 1)

	mmUpdate.t.Helper()

	if mmUpdate.inspectFuncUpdate != nil {
		mmUpdate.inspectFuncUpdate(ctx, actorID, scopeAll, id, roleSlugs, email, username)
	}

	mm_params := UsersSvcMockUpdateParams{ctx, actorID, scopeAll, id, roleSlugs, email, username}

	// Record call args
	mmUpdate.UpdateMock.mutex.Lock()
	mmUpdate.UpdateMock.callArgs = append(mmUpdate.UpdateMock.callArgs, &mm_params)
	mmUpdate.UpdateMock.mutex.Unlock()

	for _, e := range mmUpdate.UpdateMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.u1, e.results.err
		}
	}

	if mmUpdate.UpdateMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmUpdate.UpdateMock.defaultExpectation.Counter, 1)
		mm_want := mmUpdate.UpdateMock.defaultExpectation.params
		mm_want_ptrs := mmUpdate.UpdateMock.defaultExpectation.paramPtrs

		mm_got := UsersSvcMockUpdateParams{ctx, actorID, scopeAll, id, roleSlugs, email, username}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.actorID != nil && !minimock.Equal(*mm_want_ptrs.actorID, mm_got.actorID) {
				mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameter actorID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.originActorID, *mm_want_ptrs.actorID, mm_got.actorID, minimock.Diff(*mm_want_ptrs.actorID, mm_got.actorID))
			}

			if mm_want_ptrs.scopeAll != nil && !minimock.Equal(*mm_want_ptrs.scopeAll, mm_got.scopeAll) {
				mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameter scopeAll, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.originScopeAll, *mm_want_ptrs.scopeAll, mm_got.scopeAll, minimock.Diff(*mm_want_ptrs.scopeAll, mm_got.scopeAll))
			}

			if mm_want_ptrs.id != nil && !minimock.Equal(*mm_want_ptrs.id, mm_got.id) {
				mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameter id, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.originId, *mm_want_ptrs.id, mm_got.id, minimock.Diff(*mm_want_ptrs.id, mm_got.id))
			}

			if mm_want_ptrs.roleSlugs != nil && !minimock.Equal(*mm_want_ptrs.roleSlugs, mm_got.roleSlugs) {
				mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameter roleSlugs, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.originRoleSlugs, *mm_want_ptrs.roleSlugs, mm_got.roleSlugs, minimock.Diff(*mm_want_ptrs.roleSlugs, mm_got.roleSlugs))
			}

			if mm_want_ptrs.email != nil && !minimock.Equal(*mm_want_ptrs.email, mm_got.email) {
				mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameter email, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.originEmail, *mm_want_ptrs.email, mm_got.email, minimock.Diff(*mm_want_ptrs.email, mm_got.email))
			}

			if mm_want_ptrs.username != nil && !minimock.Equal(*mm_want_ptrs.username, mm_got.username) {
				mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameter username, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.originUsername, *mm_want_ptrs.username, mm_got.username, minimock.Diff(*mm_want_ptrs.username, mm_got.username))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmUpdate.t.Errorf("UsersSvcMock.Update got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpdate.UpdateMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmUpdate.UpdateMock.defaultExpectation.results
		if mm_results == nil {
			mmUpdate.t.Fatal("No results are set for the UsersSvcMock.Update")
		}
		return (*mm_results).u1, (*mm_results).err
	}
	if mmUpdate.funcUpdate != nil {
		return mmUpdate.funcUpdate(ctx, actorID, scopeAll, id, roleSlugs, email, username)
	}
	mmUpdate.t.Fatalf("Unexpected call to UsersSvcMock.Update. %v %v %v %v %v %v %v", ctx, actorID, scopeAll, id, roleSlugs, email, username)
	return
}

// UpdateAfterCounter returns a count of finished UsersSvcMock.Update invocations
func (mmUpdate *UsersSvcMock) UpdateAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpdate.afterUpdateCounter)
}

// UpdateBeforeCounter returns a count of UsersSvcMock.Update invocations
func (mmUpdate *UsersSvcMock) UpdateBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpdate.beforeUpdateCounter)
}

// Calls returns a list of arguments used in each call to UsersSvcMock.Update.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmUpdate *mUsersSvcMockUpdate) Calls() []*UsersSvcMockUpdateParams {
	mmUpdate.mutex.RLock()

	argCopy := make([]*UsersSvcMockUpdateParams, len(mmUpdate.callArgs))
	copy(argCopy, mmUpdate.callArgs)

	mmUpdate.mutex.RUnlock()

	return argCopy
}

// MinimockUpdateDone returns true if the count of the Update invocations corresponds
// the number of defined expectations
func (m *UsersSvcMock) MinimockUpdateDone() bool {
	if m.UpdateMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.UpdateMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.UpdateMock.invocationsDone()
}

// MinimockUpdateInspect logs each unmet expectation
func (m *UsersSvcMock) MinimockUpdateInspect() {
	for _, e := range m.UpdateMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to UsersSvcMock.Update at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdateCounter := mm_atomic.LoadUint64(&m.afterUpdateCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdateMock.defaultExpectation != nil && afterUpdateCounter < 1 {
		if m.UpdateMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to UsersSvcMock.Update at\n%s", m.UpdateMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to UsersSvcMock.Update at\n%s with params: %#v", m.UpdateMock.defaultExpectation.expectationOrigins.origin, *m.UpdateMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdate != nil && afterUpdateCounter < 1 {
		m.t.Errorf("Expected call to UsersSvcMock.Update at\n%s", m.funcUpdateOrigin)
	}

	if !m.UpdateMock.invocationsDone() && afterUpdateCounter > 0 {
		m.t.Errorf("Expected %d calls to UsersSvcMock.Update at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdateMock.expectedInvocations), m.UpdateMock.expectedInvocationsOrigin, afterUpdateCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *UsersSvcMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockChangePasswordInspect()

			m.MinimockCreateInspect()

			m.MinimockFreezeInspect()

			m.MinimockGetInspect()

			m.MinimockListInspect()

			m.MinimockMarkTourSeenInspect()

			m.MinimockResolveLoginsInspect()

			m.MinimockRestoreInspect()

			m.MinimockSetOwnerInspect()

			m.MinimockSetPasswordInspect()

			m.MinimockSetTOTPRequiredInspect()

			m.MinimockSoftDeleteInspect()

			m.MinimockUnfreezeInspect()

			m.MinimockUpdateInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *UsersSvcMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *UsersSvcMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockChangePasswordDone() &&
		m.MinimockCreateDone() &&
		m.MinimockFreezeDone() &&
		m.MinimockGetDone() &&
		m.MinimockListDone() &&
		m.MinimockMarkTourSeenDone() &&
		m.MinimockResolveLoginsDone() &&
		m.MinimockRestoreDone() &&
		m.MinimockSetOwnerDone() &&
		m.MinimockSetPasswordDone() &&
		m.MinimockSetTOTPRequiredDone() &&
		m.MinimockSoftDeleteDone() &&
		m.MinimockUnfreezeDone() &&
		m.MinimockUpdateDone()
}
